import json, math, re
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path

analysis_path = Path('/root/refill_analysis.json')
summary_path = Path('/root/refill_summary.md')
with analysis_path.open() as f:
    data = json.load(f)

errors = []
expected_keys = ['assumptions', 'medications', 'totals', 'recommendation']
if list(data.keys()) != expected_keys:
    errors.append(f'top-level keys are {list(data.keys())}, expected {expected_keys}')
if len(data.get('medications', [])) != 10:
    errors.append(f'medications length is {len(data.get("medications", []))}, expected 10')

def is_rounded_2(x):
    if not isinstance(x, (int, float)):
        return True
    # currency values generated as JSON numbers cannot preserve trailing zeros;
    # verify numeric value equals itself rounded to cents.
    return abs(x - round(x, 2)) < 1e-9

currency_key_markers = ('usd', 'cost', 'price', 'revenue', 'reimbursement', 'difference')
for container_name in ['medications']:
    for i, med in enumerate(data[container_name]):
        for k, v in med.items():
            if any(marker in k.lower() for marker in currency_key_markers):
                if not is_rounded_2(v):
                    errors.append(f'{container_name}[{i}].{k} not rounded to 2 decimals: {v}')
for k, v in data['totals'].items():
    if any(marker in k.lower() for marker in currency_key_markers):
        if not is_rounded_2(v):
            errors.append(f'totals.{k} not rounded to 2 decimals: {v}')

decision = data['recommendation'].get('decision')
if decision not in {'switch_to_100_day', 'keep_90_day'}:
    errors.append(f'invalid decision: {decision}')

total_diff = data['totals']['total_annual_revenue_difference_100_minus_90_usd']
abs_diff = data['totals']['absolute_total_revenue_difference_usd']
if round(abs(total_diff), 2) != abs_diff:
    errors.append(f'abs diff mismatch: {abs_diff} vs abs({total_diff})')
expected_decision = 'switch_to_100_day' if abs_diff < 16000 else 'keep_90_day'
if decision != expected_decision:
    errors.append(f'decision rule mismatch: got {decision}, expected {expected_decision}')

summary_text = summary_path.read_text()
summary_lines = summary_text.splitlines()
if not (4 <= len(summary_lines) <= 8):
    errors.append(f'summary line count {len(summary_lines)} not 4-8')
for label in ['Total 90-day annual revenue', 'Total 100-day annual revenue', 'Absolute revenue difference']:
    if label not in summary_text or 'USD' not in summary_text:
        errors.append(f'summary missing {label} in USD')
if decision not in summary_text:
    errors.append(f'summary missing decision slug {decision}')

# Spot check Amlodipine 5mg manually per formulas
m = data['medications'][0]
ppk = m['price_per_1000_tablets_usd']
vp = m['vial_price_usd']
reimb = m['reimbursement_per_fill_300_patients_usd']
expected = {
    'annual_drug_cost_90_day_usd': round((90 * 300 * 4 * ppk) / 1000, 2),
    'annual_drug_cost_100_day_usd': round((100 * 300 * 3 * ppk) / 1000, 2),
    'annual_supply_cost_90_day_usd': round(vp * 300 * 4, 2),
    'annual_supply_cost_100_day_usd': round(vp * 300 * 3, 2),
    'annual_reimbursement_90_day_usd': round(reimb * 4, 2),
    'annual_reimbursement_100_day_usd': round(reimb * 3, 2),
}
expected['annual_revenue_90_day_usd'] = round(expected['annual_reimbursement_90_day_usd'] - expected['annual_drug_cost_90_day_usd'] - expected['annual_supply_cost_90_day_usd'], 2)
expected['annual_revenue_100_day_usd'] = round(expected['annual_reimbursement_100_day_usd'] - expected['annual_drug_cost_100_day_usd'] - expected['annual_supply_cost_100_day_usd'], 2)
for k, expected_value in expected.items():
    if m[k] != expected_value:
        errors.append(f'spot check {m["medication"]} {k}: got {m[k]}, expected {expected_value}')

if errors:
    print('VALIDATION FAILED')
    for e in errors:
        print('-', e)
    raise SystemExit(1)
print('VALIDATION PASSED')
print(f'Top-level keys: {list(data.keys())}')
print(f'Medication count: {len(data["medications"])}')
print(f'Decision: {decision}')
print(f'abs(total_diff): {abs_diff}')
print('Spot-check medication:', m['medication'])
for k in expected:
    print(f'{k}: {m[k]}')

